SELECT p.product_id AS id, p.product_name AS title, p.price AS price, p.main_image_url AS img, p.region_display_name AS loc, p.created_at AS time, false AS reserved, p.like_count AS likeCount, false AS liked
FROM products p
WHERE p.product_id IN
#{id}
ORDER BY FIELD(p.product_id,
#{id}
)
